31	// Default images for the two renderers.
32	const (
33		DefaultHelmImage      = "alpine/helm"
34		DefaultKustomizeImage = "registry.k8s.io/kustomize/kustomize:v5.8.1"
35	)
36	
37	// IDs of the findings the renderers themselves produce.
38	const (
39		// HelmLintID is a message helm lint reported, at WARNING or ERROR.
40		HelmLintID = "HELM-LINT"
41		// K8sRenderID is a chart or an overlay that did not render at all.
42		K8sRenderID = "K8S-RENDER"
43	)
44	
45	// helmLintLine is one message of helm lint: `[SEVERITY] path: message`, as
46	// support.Message.Error formats it.
47	var helmLintLine = regexp.MustCompile(`^\[(ERROR|WARNING|INFO|UNKNOWN)\] ([^:]*): (.*)$`)
48	
49	// helmSourceLine is the comment helm template writes above each document,
50	// naming the template it came from: `# Source: <chart name>/templates/x.yaml`.
51	var helmSourceLine = regexp.MustCompile(`^# Source: (\S+)`)
52	
53	// renderer runs one tool in the repository, the way every other tool runs:
54	// in the repository for a binary, with the repository mounted read-only at
55	// /scan and as the working directory for an image.
56	func renderer(target string, tool ToolSpec, defaultImage, binary string, args ...string) toolCmd {
57		// helm gets them on lint and on template alike: only the flags the two
58		// share (--values, --set…) make sense there.
59		args = afterSubcommand(args, tool.Args)
60		if tool.Source != ToolSourceContainer {
61			name := tool.Binary
62			if name == "" {
63				name = binary
64			}
65			return toolCmd{Name: name, Args: args, Dir: target}
66		}
67		return containerRun{
68			Flags: []string{"-v", target + ":" + containerScanPath + ":ro", "-w", containerScanPath},
69			Image: orDefault(tool.Image, defaultImage),
70			Argv:  args,
71		}.cmd()
72	}
73	
74	func orDefault(v, def string) string {
75		if v == "" {
76			return def
77		}
78		return v
79	}
80	
81	func helmArgs(target, chart string, tool ToolSpec, sub string) toolCmd {
82		return renderer(target, tool, DefaultHelmImage, "helm", sub, chart)
83	}
84	
85	func kustomizeArgs(target, dir string, tool ToolSpec) toolCmd {
86		return renderer(target, tool, DefaultKustomizeImage, "kustomize", "build", dir)
87	}
88	
89	// kubeconformStdinArgs validates what arrives on stdin. A container gets -i
90	// and no repository mount: it reads nothing but its input and its cache.
91	func kubeconformStdinArgs(rendered []byte, tool ToolSpec, opts KubeconformOptions) toolCmd {
92		flags := kubeconformFlags(tool, opts)
93		if tool.Source != ToolSourceContainer {
94			return toolCmd{Name: kubeconformBinary(tool), Args: append(flags, "-"), Stdin: rendered}
95		}
96		engineArgs := []string{"-i"}
97		if opts.CacheDir != "" {
98			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
99		}
100		return containerRun{
101			Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
102		}.cmd()
103	}
