105	// k8sValidation is one schema stage over one repository: the tools it has,
106	// what it validates against, and the report it fills in.
107	type k8sValidation struct {
108		target      string
109		kubeconform ToolSpec
110		opts        KubeconformOptions
111		report      *KubeconformReport
112	}
113	
114	// available reports whether an optional renderer was resolved at all.
115	func available(tool ToolSpec) bool {
116		return tool.Source != ToolSourceNone && tool.Source != ""
117	}
