143	// schemaFindings is one finding per field the schema rejected, so each one has
144	// its own line and can be fixed on its own.
145	func schemaFindings(r kubeconformResource, content []byte) []Finding {
146		problems := r.ValidationErrors
147		if len(problems) == 0 {
148			// An invalid resource with no field detail still gets reported, on the
149			// resource as a whole.
150			problems = []kubeconformFieldProblem{{Msg: r.Msg}}
151		}
152		out := make([]Finding, 0, len(problems))
153		for _, p := range problems {
154			f := k8sFinding(r, K8sSchemaID)
155			f.Title = fmt.Sprintf("%s: %s", resourceLabel(r), p.Msg)
156			f.Description = fmt.Sprintf("The resource does not match the schema of %s %s: the API server would reject it.", r.Version, r.Kind)
157			f.Message = strings.TrimSpace(pointerLabel(p.Path) + " " + p.Msg)
158			f.Resolution = "Correct the field so it matches the API's schema for this kind and apiVersion."
159			f.Line, f.EndLine = locateProblem(content, r, p)
160			out = append(out, f)
161		}
162		return out
163	}
164	
165	// errorFinding classifies a resource kubeconform could not validate. The
166	// second result says it is a custom resource, which is skipped rather than
167	// reported: its schema is not missing, it lives somewhere kubeconform does not
168	// look.
169	func errorFinding(r kubeconformResource, version string, content []byte) (Finding, bool) {
170		if strings.HasPrefix(r.Msg, kubeconformMissingSchema) {
171			if !builtinGroups[apiGroup(r.Version)] {
172				return Finding{}, true
173			}
174			f := k8sFinding(r, K8sAPIRemovedID)
175			f.Title = fmt.Sprintf("%s: %s %s is not served by Kubernetes %s", resourceLabel(r), r.Version, r.Kind, version)
176			f.Description = "This apiVersion has been removed from the Kubernetes release the manifests are validated against: the API server would refuse the resource."
177			f.Message = r.Msg
178			f.Resolution = fmt.Sprintf("Migrate %s to an apiVersion Kubernetes %s serves; some migrations also change fields.", r.Kind, version)
179			f.References = []string{K8sDeprecationGuide}
180			if span, ok := k8s.DocumentField(content, r.Kind, r.Name, "apiVersion"); ok {
181				f.Line, f.EndLine = span.Line, span.EndLine
182			}
183			return f, false
184		}
185		f := k8sFinding(r, K8sParseID)
186		f.Title = "Cannot be read as a Kubernetes resource"
187		if r.Kind != "" {
188			f.Title = resourceLabel(r) + ": cannot be read as a Kubernetes resource"
189		}
190		f.Description = "kubeconform could not parse this document as a resource."
191		f.Message = r.Msg
192		f.Resolution = "Check the document's YAML syntax and that it carries apiVersion, kind and metadata."
193		return f, false
194	}
195	
196	// k8sFinding is what every kubeconform finding shares.
197	func k8sFinding(r kubeconformResource, id string) Finding {
198		return Finding{
199			ID:       id,
200			Severity: SeverityHigh,
201			Source:   SourceKubeconform,
202			File:     r.Filename,
203			IaCType:  "kubernetes",
204		}
205	}
206	
207	// locateProblem finds the line of one rejected field. An unknown field is
208	// reported at its parent, with the key in the message; the key's own line is
209	// the one to show, and the parent's is the fallback.
210	func locateProblem(content []byte, r kubeconformResource, p kubeconformFieldProblem) (int, int) {
211		if content == nil {
212			return 0, 0
213		}
214		if m := additionalProperty.FindStringSubmatch(p.Msg); m != nil {
215			if span, ok := k8s.Locate(content, r.Kind, r.Name, strings.TrimSuffix(p.Path, "/")+"/"+escapePointer(m[1])); ok {
216				return span.Line, span.EndLine
217			}
218		}
219		if span, ok := k8s.Locate(content, r.Kind, r.Name, p.Path); ok {
220			return span.Line, span.EndLine
221		}
222		return 0, 0
223	}
224	
225	// apiGroup is the group of an apiVersion: "apps" for apps/v1, "" for v1.
226	func apiGroup(apiVersion string) string {
227		if i := strings.LastIndex(apiVersion, "/"); i >= 0 {
228			return apiVersion[:i]
229		}
230		return ""
231	}
232	
233	func resourceLabel(r kubeconformResource) string {
234		if r.Name == "" {
235			return r.Kind
236		}
237		return r.Kind + "/" + r.Name
238	}
239	
240	func pointerLabel(path string) string {
241		if path == "" {
242			return ""
243		}
244		return path + ":"
245	}
246	
247	func escapePointer(key string) string {
248		return strings.ReplaceAll(strings.ReplaceAll(key, "~", "~0"), "/", "~1")
249	}

