97		if opts.CacheDir != "" {
98			engineArgs = append(engineArgs, "-v", opts.CacheDir+":"+kubeconformCacheMount)
99		}
100		return containerRun{
101			Flags: engineArgs, Image: kubeconformImage(tool.Image), Argv: append(flags, "-"), Stdin: rendered,
102		}.cmd()
103	}
