119	// renderCharts lints, renders and validates each chart. Without helm, every
120	// chart is reported as not rendered.
121	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
122		tool := v.opts.Helm
123		for _, chart := range charts {
124			if !available(tool) {
125				v.report.Unrendered = append(v.report.Unrendered, chart)
126				continue
127			}
128			lint := helmLint(ctx, v.target, chart, tool)
129			v.report.Findings = append(v.report.Findings, lint...)
130	
131			cmd := helmArgs(v.target, chart, tool, "template")
132			log.Printf("Running: %s", cmd)
133			rendered, err := runner.Run(ctx, cmd, nil)
134			if err != nil {
135				if ctx.Err() != nil {
136					return ctx.Err()
137				}
138				// helm lint renders the chart too, so a chart that does not
139				// render has usually been reported by it already, with more to
140				// say. The render failure is the fallback, not a second copy.
141				if !hasError(lint) {
142					v.report.Findings = append(v.report.Findings,
143						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", err))
144				}
145				continue
146			}
147			origins := helmOrigins(rendered, chart)
148			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
149				if file, ok := origins[kind+"/"+name]; ok {
150					return file
151				}
152				return chart
153			})
154			if err != nil {
155				return fmt.Errorf("chart %s: %w", chart, err)
156			}
157		}
158		return nil
159	}
