314	// renderFailure is a chart or an overlay that could not be rendered: nothing
315	// in it was validated, and `helm install` or `kubectl apply -k` would fail the
316	// same way.
317	func renderFailure(source, dialect, file, title string, err error) Finding {
318		detail := err.Error()
319		var exitErr *exitError
320		if errors.As(err, &exitErr) && exitErr.Stderr != "" {
321			detail = strings.TrimSpace(exitErr.Stderr)
322		}
