324		return Finding{
325			ID:          K8sRenderID,
326			Title:       title + ": " + first,
327			Description: "The directory could not be rendered, so none of its resources were validated.",
328			Message:     detail,
329			Resolution:  "Render it locally and fix what the tool reports; a chart's dependencies must be vendored in charts/ or fetched with helm dependency build.",
330			Severity:    SeverityHigh,
331			Source:      source,
332			File:        file,
333			IaCType:     dialect,
334		}
