84	// ── Availability ─────────────────────────────────────────────────────────────
85	
86	// canFixMisconfig is the one computation behind the shortcut column and the
87	// handler (Rule 130). It answers in the order the user would ask: am I in the
88	// right place, is there a row, can its file be written at all, and is this rule
89	// one the catalog knows.
90	//
91	// The last question runs the fix itself. That is deliberate: a rule can be in
92	// the catalog and still decline this instance — a base image whose distribution
93	// cannot be identified, a stage that already sets a user — and greying out on
94	// "the catalog has an entry" while the handler then refuses would be exactly
95	// the two computations Rule 130 forbids.
96	func (m Model) canFixMisconfig() shortcut.Availability {
97		if m.activeTab != TabMisconfig {
98			return shortcut.Unavailable(reasonNotMisconfigTab)
99		}
100		f, ok := m.findingsTable.Selected()
101		if !ok {
102			return shortcut.Unavailable(reasonNoFinding)
103		}
104		if m.result == nil || m.result.TargetType != scan.TargetDirectory {
105			return shortcut.Unavailable(reasonFileNotOnDisk)
106		}
107		rule, ok := remediation.FixFor(f)
108		if !ok {
109			return shortcut.Unavailable(noFixReason(f))
110		}
111		// A refusal the finding alone settles (DEVDESK-688): greyed in advance, with
112		// the reason the press of the key would give.
113		if rule.Declines != nil {
114			if reason := rule.Declines(f); reason != "" {
115				return shortcut.Unavailable(reason)
116			}
117		}
118		// Reading the file here would be I/O on a path the header calls every
119		// frame, so the declines that need the content are left to the Cmd and
120		// reach the footer. What is settled here is everything the finding alone
121		// can answer.
122		return shortcut.Availability{}
123	}
124	
125	// noFixReason is why a finding with no fix in the catalog is refused: for a Pod
126	// Security finding, what the manifest is missing (DEVDESK-689); for anything
127	// else, the generic refusal. The fix is tried first, so a rule that has one never
128	// reaches the missing text.
129	func noFixReason(f scan.Finding) string {
130		if text, ok := remediation.MissingFor(f); ok {
131			return text
132		}
133		return remediation.ReasonNoFixForRule
134	}
135	
136	// ── Preparing ────────────────────────────────────────────────────────────────
137	
138	// prepareMisconfigFix starts the fix by computing it: nothing is asked of the
139	// user until the file has been read, rewritten and put to git, so the
140	// confirmation can state what it is about.
141	func (m Model) prepareMisconfigFix() (tea.Model, tea.Cmd) {
142		if a := m.canFixMisconfig(); !a.Enabled() {
143			return m, m.footer.Warn(a.Reason)
144		}
145		f, _ := m.findingsTable.Selected()
146		return m, prepareMisconfigFixCmd(m.targetPath, f)
147	}
148	
149	// prepareMisconfigFixCmd reads the file, asks the catalog for the edits and
150	// applies them. The finding is copied in (Rule 110).
151	//
152	// A rule that declines here is not an error: it is an answer, and it reaches the
153	// footer as a warning rather than as a failure.
154	func prepareMisconfigFixCmd(target string, f scan.Finding) tea.Cmd {
155		return func() tea.Msg {
156			rule, ok := remediation.FixFor(f)
157			if !ok {
158				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{noFixReason(f)}}
159			}
160			rel, reason := rule.FileFor(target, f)
161			if reason != "" {
162				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
163			}
164			path := filepath.Join(target, filepath.FromSlash(rel))
165			original, err := readFile(path)
166			if err != nil {
167				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: err}
168			}
169			edits, reason := rule.Fix(original, f)
170			if reason != "" {
171				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: errDeclined{reason}}
172			}
173			updated, err := patch.Rewrite(original, edits)
174			if err != nil {
175				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
176			}
177			diff, err := patch.Diff(rel, original, edits)
178			if err != nil {
179				return MisconfigFixPreparedMsg{Target: target, Rule: f.ID, Err: fmt.Errorf("%s: %w", rel, err)}
180			}
181			file := preparedWrite{File: rel, Path: path, Original: original, Updated: updated}
182			if file.State, err = git.StateOf(path); err != nil {
183				log.Printf("ERROR [security/misconfig] git state of %s: %v", rel, err)
184				file.StateErr = true
185			}
186			body := rule.Title + "\n\n"
187			if rule.Warning != "" {
188				body += "Warning: " + rule.Warning + "\n\n"
189			}
190			return MisconfigFixPreparedMsg{
191				Target: target, File: file, FindingFile: f.File,
192				Rule: f.ID, Instance: instanceOf(f), Body: body + diff,
193				Scope: rule.ScopeOf(updated, edits),
194			}
195		}
196	}
197	
198	// errDeclined carries a catalog refusal through the same channel as a failure,
199	// so the handler has one message to read, and tells the two apart by type rather
200	// than by inspecting a string.
201	type errDeclined struct{ reason string }
202	
203	func (e errDeclined) Error() string { return e.reason }
204	
205	// ── Confirming and writing ───────────────────────────────────────────────────
206	
207	func (m Model) handleMisconfigFixPrepared(msg MisconfigFixPreparedMsg) (tea.Model, tea.Cmd) {
208		if msg.Target != m.targetPath {
209			return m, nil // an answer about a result no longer on screen
210		}
211		if d, ok := msg.Err.(errDeclined); ok {
212			// Nothing failed: the catalog will not fix this instance, and says why.
213			return m, m.footer.Warn(d.reason)
214		}
215		if msg.Err != nil {
216			log.Printf("ERROR [security/misconfig] prepare fix: %v", msg.Err)
217			return m, m.footer.Error("Could not prepare the fix — the file may have changed, check logs")
218		}
219		m.misconfigPending = &msg.File
220		m.misconfigFinding = misconfigFindingRef{Rule: msg.Rule, Instance: msg.Instance, File: msg.FindingFile, Scope: msg.Scope}
221		// Rule 104: the safe answer is the default — ConfirmModal opens on No.
222		m.confirmModal = sharedcomponents.NewConfirmModal("Fix misconfiguration", misconfigConfirmationText(msg.File, msg.Body))
223		return m, nil
224	}
225	
226	// misconfigConfirmationText shows the diff itself, not a summary of it.
227	//
228	// A base image bump is one token replaced by another and reads as a sentence; a
229	// misconfiguration fix inserts a block, and no sentence conveys what is about to
230	// land in the file. What the user agrees to is the diff, so the diff is what the
231	// modal shows — followed by what git will and will not be able to undo.
232	func misconfigConfirmationText(f preparedWrite, body string) string {
233		return body + "\n" + fmt.Sprintf("%s: %s\n", f.File, gitAdvice(f))
234	}
235	
236	// handleMisconfigFixConfirmed runs the write the modal was about.
237	func (m Model) handleMisconfigFixConfirmed() (tea.Model, tea.Cmd) {
238		file, ref := m.misconfigPending, m.misconfigFinding
239		m.misconfigPending = nil
240		m.misconfigFinding = misconfigFindingRef{}
241		m.confirmModal = nil
242		if file == nil {
243			return m, nil
244		}
245		return m, writeMisconfigFixCmd(m.targetPath, ref, *file)
246	}
247	
248	func writeMisconfigFixCmd(target string, ref misconfigFindingRef, f preparedWrite) tea.Cmd {
249		return func() tea.Msg {
250			err := patch.WriteIfUnchanged(f.Path, f.Original, f.Updated)
251			return MisconfigFixWrittenMsg{
252				Target: target, File: f.File, FindingFile: ref.File,
253				Rule: ref.Rule, Instance: ref.Instance, Scope: ref.Scope, Err: err,
254			}
255		}
256	}
257	
258	// misconfigFindingRef is the finding a pending fix is about, kept between the
259	// confirmation and the write so the verification knows what to look for.
260	type misconfigFindingRef struct {
261		// Rule is the AVD id.
262		Rule string
263		// Instance is which occurrence of it, so a file holding the same rule
264		// twice is not judged by the one the fix did not touch.
265		Instance string
266		// File is where the finding points, which is not always the file written.
267		File string
268		// Scope is the workload the fix clears, when it clears one.
269		Scope remediation.Scope
270	}
271	
272	func (m Model) handleMisconfigFixWritten(msg MisconfigFixWrittenMsg) (tea.Model, tea.Cmd) {
273		if msg.Target != m.targetPath {
274			return m, nil
275		}
276		if msg.Err != nil {
277			cmd := m.reportFailedFix(msg)
278			return m, cmd
279		}
280		// The file changed; the result did not. A re-scan is what turns "written"
281		// into "fixed", so it starts here rather than being left to the user — as a
282		// job, visible in `:jobs` and stoppable with K.
283		v := misconfigVerify{Target: msg.Target, Rule: msg.Rule, File: msg.FindingFile, Instance: msg.Instance, Scope: msg.Scope}
284		m.misconfigVerifying = &v
285		scan := m.startMisconfigVerification(v)
286		footer := m.footer.Info(fmt.Sprintf("Fixed %s — re-scanning to confirm %s is gone", msg.File, msg.Rule))
287		return m, tea.Batch(scan, footer)
288	}
289	
290	// reportFailedFix sets the footer on the model it is called on, which is why it
291	// takes a pointer: on a copy the message would be set and then thrown away.
292	func (m *Model) reportFailedFix(msg MisconfigFixWrittenMsg) tea.Cmd {
293		if errors.Is(msg.Err, patch.ErrChanged) {
294			return m.footer.Error(fmt.Sprintf("%s changed since the preview — review it again", msg.File))
295		}
296		log.Printf("ERROR [security/misconfig] write %s: %v", msg.File, msg.Err)
297		return m.footer.Error(fmt.Sprintf("Failed to write %s — check logs", msg.File))
298	}
299	
300	// ── Verifying (§3.78, phase B3) ──────────────────────────────────────────────
301	//
302	// A written file is not a fixed one. The rule that was faulted is still in the
303	// result on screen, because that result was measured before the edit — and the
304	// whole discipline §3.2 set for base images is that a fix is judged by a
305	// re-scan, never by the confidence of whatever produced it. So the write starts
306	// one, and the verdict it reports is binary: the rule is gone, or it is not.
307	//
308	// The scan is an ordinary job (§3.58), which is what makes starting it on the
309	// user's behalf acceptable: it shows up in `:jobs` with a label saying why, and
310	// `K` stops it. Nothing is hidden and nothing is unstoppable.
311	
312	// misconfigVerify is the fix waiting on a re-scan to say whether it worked.
313	type misconfigVerify struct {
314		Target string
315		Rule   string
316		// File is the file the finding points at, where the rule is looked for.
317		File     string
318		Instance string
319		// Scope is what a rule that clears a whole workload is looked for in
320		// (DEVDESK-688). The zero value: this occurrence, through holdsRule.
321		Scope remediation.Scope
322	}
323	
324	// MisconfigVerifiedMsg is the verdict: whether the rule the fix was about is
325	// still reported for that file.
326	type MisconfigVerifiedMsg struct {
327		Target  string
328		Rule    string
329		File    string
330		Cleared bool
331		// Scope is the scope the verdict was judged by; the zero value for a fix of
332		// one occurrence.
333		Scope remediation.Scope
334		// Still lists the rule ids the re-scan still reports in the scope of the
335		// fix; Cleared is true when it is empty (DEVDESK-688).
336		Still []string
337		// Result is the scan the verdict was read from, so the tab can stop showing
338		// findings the edit has already dealt with.
339		Result *scan.Result
340		Err    error
341	}
342	
343	// startMisconfigVerification re-scans the target the fix was written into.
344	//
345	// It runs even when the catalog is sure of itself, because being sure is not
346	// the same as having measured — and the cases where a rule survives its own fix
347	// are exactly the ones nobody predicted.
348	func (m Model) startMisconfigVerification(v misconfigVerify) tea.Cmd {
349		if m.scanningTarget(v.Target) {
350			// Something is already measuring this target; its result will answer.
351			return nil
352		}
353		job := inventoryScanJob{Kind: kindRepo, Name: v.Target}
354		opts := m.scanOptions()
355		return jobs.StartInContext(
356			jobs.NewRun(jobs.KindScan, command.ViewSecurity, "", "verify fix", v.Target),
357			func(contextName string) tea.Cmd {
358				return rescanCmd([]inventoryScanJob{job}, opts, contextName)
359			},
360		)
361	}
362	
363	// verifyMisconfigCmd reads the result the re-scan stored and answers whether the
364	// rule is still there. It runs off Update (Rule 110).
365	func verifyMisconfigCmd(v misconfigVerify) tea.Cmd {
366		return func() tea.Msg {
367			result, err := cache.ReadWorkspaceScanResult(v.Target)
368			if err != nil {
369				return MisconfigVerifiedMsg{Target: v.Target, Rule: v.Rule, File: v.File, Err: err}
370			}
371			still := stillReported(result, v)
372			return MisconfigVerifiedMsg{
373				Target: v.Target, Rule: v.Rule, File: v.File,
374				Cleared: len(still) == 0, Still: still, Scope: v.Scope, Result: result,
375			}
376		}
377	}
378	
379	// stillReported lists the rule ids the result still reports for the fix v.
380	//
381	// Without a scope it is holdsRule on the occurrence that was fixed. With one, it
382	// is each rule of the scope looked for in the lines of the edited workload: one
383	// edit cleared them for every container of the pod, so a finding on another
384	// container still counts, and a finding of another workload of the file does not.
385	// A scope with no lines (0, 0: the computation failed) reads the whole file, the
386	// safe side: "still reported" at worst, never a "fixed" that was not measured.
387	func stillReported(result *scan.Result, v misconfigVerify) []string {
388		if len(v.Scope.Rules) == 0 {
389			if holdsRule(result, v.Rule, v.File, v.Instance) {
390				return []string{v.Rule}
391			}
392			return nil
393		}
394		if result == nil {
395			return nil
396		}
397		var still []string
398		for _, rule := range v.Scope.Rules {
399			if holdsRuleInScope(result, rule, v.File, v.Scope) {
400				still = append(still, rule)
401			}
402		}
403		return still
404	}
405	
406	// holdsRuleInScope says whether the result reports rule in file, at a line that
407	// is inside the scope's lines (anywhere in the file when the scope has none). A
408	// finding with no line (Line <= 0) cannot be placed outside the scope, so it
409	// counts as inside: the safe side.
410	func holdsRuleInScope(result *scan.Result, rule, file string, scope remediation.Scope) bool {
411		want := remediation.RuleKey(rule)
412		wholeFile := scope.Line == 0 && scope.EndLine == 0
413		for _, f := range result.Findings {
414			if scan.Categorize(f) != scan.CategoryMisconfiguration || f.File != file || remediation.RuleKey(f.ID) != want {
415				continue
416			}
417			if wholeFile || f.Line <= 0 || (f.Line >= scope.Line && f.Line <= scope.EndLine) {
418				return true
419			}
420		}
421		return false
422	}
423	
424	// holdsRule says whether a result still reports this rule for this file —
425	// and, when instance is set, this occurrence of it.
426	//
427	// It matches through remediation.RuleKey rather than on the string, for the
428	// reason the catalog does: Trivy spells one rule two ways, and a comparison
429	// that missed the other spelling would report every fix as successful.
430	//
431	// The occurrence matters for a manifest (§3.80): a Deployment with two
432	// containers is flagged for KSV-0001 twice in one file, and the fix edits one
433	// of them. Judged on the rule and the file alone, the untouched container
434	// would read as the fix having failed.
435	func holdsRule(result *scan.Result, rule, file, instance string) bool {
436		if result == nil {
437			return false
438		}
439		want := remediation.RuleKey(rule)
440		for _, f := range result.Findings {
441			if scan.Categorize(f) != scan.CategoryMisconfiguration {
442				continue
443			}
444			if f.File == file && remediation.RuleKey(f.ID) == want && (instance == "" || instanceOf(f) == instance) {
445				return true
446			}
447		}
448		return false
449	}
450	
451	// instanceOf identifies one occurrence of a rule in a file, without its line,
452	// which the fix itself moves. Trivy words the occurrence in Message ("Container
453	// 'api' of Deployment 'web' should set…"), kubeconform in Title
454	// ("Deployment/web: …"); the pair covers both.
455	func instanceOf(f scan.Finding) string {
456		return f.Title + "\n" + f.Message
457	}
458	
459	// handleMisconfigVerified reports the verdict, and swaps in the result it was
460	// read from.
461	//
462	// The swap is what keeps the screen from contradicting the footer: without it a
463	// line saying the rule is gone would sit above a table still listing it.
464	func (m Model) handleMisconfigVerified(msg MisconfigVerifiedMsg) (tea.Model, tea.Cmd) {
465		if msg.Target != m.targetPath {
466			return m, nil
467		}
468		m.misconfigVerifying = nil
469		if msg.Err != nil {
470			log.Printf("ERROR [security/misconfig] verify %s: %v", msg.Rule, msg.Err)
471			return m, m.footer.Error("Could not read the verification scan — check logs")
472		}
473		if msg.Result != nil {
474			m.setResult(msg.Result)
475		}
476		if !msg.Cleared {
477			// Not a failure: the file was written, and the rule still fires. Saying
478			// so is the only honest answer, and it is why the scan exists.
479			ids := msg.Still
480			if len(ids) == 0 {
481				ids = []string{msg.Rule}
482			}
483			return m, m.footer.Warn(fmt.Sprintf("%s still reported in %s after the fix", strings.Join(ids, " and "), msg.File))
484		}
485		if len(msg.Scope.Rules) > 0 {
486			return m, m.footer.Info(fmt.Sprintf("%s cleared for the whole pod in %s — confirmed by a re-scan",
487				strings.Join(msg.Scope.Rules, " and "), msg.File))
488		}
489		return m, m.footer.Info(fmt.Sprintf("%s cleared in %s — confirmed by a re-scan", msg.Rule, msg.File))
490	}
