119	// renderCharts lints, renders and validates each chart. Without helm, every
120	// chart is reported as not rendered.
121	func (v *k8sValidation) renderCharts(ctx context.Context, charts []string) error {
122		tool := v.opts.Helm
123		for _, chart := range charts {
124			if !available(tool) {
125				v.report.Unrendered = append(v.report.Unrendered, chart)
126				continue
127			}
128			lint := helmLint(ctx, v.target, chart, tool)
129			v.report.Findings = append(v.report.Findings, lint...)
130	
131			cmd := helmArgs(v.target, chart, tool, "template")
132			log.Printf("Running: %s", cmd)
133			rendered, err := runner.Run(ctx, cmd, nil)
134			if err != nil {
135				if ctx.Err() != nil {
136					return ctx.Err()
137				}
138				// helm lint renders the chart too, so a chart that does not
139				// render has usually been reported by it already, with more to
140				// say. The render failure is the fallback, not a second copy.
141				if !hasError(lint) {
142					v.report.Findings = append(v.report.Findings,
143						renderFailure(SourceHelm, "helm", path.Join(chart, "Chart.yaml"), "Chart does not render", err))
144				}
145				continue
146			}
147			origins := helmOrigins(rendered, chart)
148			err = v.validateRendered(ctx, rendered, "helm", func(kind, name string) string {
149				if file, ok := origins[kind+"/"+name]; ok {
150					return file
151				}
152				return chart
153			})
154			if err != nil {
155				return fmt.Errorf("chart %s: %w", chart, err)
156			}
157		}
158		return nil
159	}
160	
161	// renderKustomizations builds and validates each overlay. Without kustomize,
162	// every overlay is reported as not rendered.
163	func (v *k8sValidation) renderKustomizations(ctx context.Context, dirs []string) error {
164		tool := v.opts.Kustomize
165		for _, dir := range dirs {
166			if !available(tool) {
167				v.report.Unrendered = append(v.report.Unrendered, dir)
168				continue
169			}
170			file := path.Join(dir, k8s.KustomizationFile(filepath.Join(v.target, filepath.FromSlash(dir))))
171			cmd := kustomizeArgs(v.target, dir, tool)
172			log.Printf("Running: %s", cmd)
173			rendered, err := runner.Run(ctx, cmd, nil)
174			if err != nil {
175				if ctx.Err() != nil {
176					return ctx.Err()
177				}
178				v.report.Findings = append(v.report.Findings,
179					renderFailure(SourceKustomize, "kustomize", file, "Overlay does not build", err))
180				continue
181			}
182			// kustomize adds no origin to what it emits unless the kustomization
183			// asks for it, and DevDesk does not write into the file to ask. The
184			// overlay is what was built, so it is what a finding points at.
185			err = v.validateRendered(ctx, rendered, "kustomize", func(string, string) string { return file })
186			if err != nil {
187				return fmt.Errorf("overlay %s: %w", dir, err)
188			}
189		}
190		return nil
191	}
192	
193	// validateRendered runs kubeconform over rendered YAML and points each
194	// finding back at the file it came from. A rendered line is not a line of
195	// any file in the repository, so these findings carry none.
196	func (v *k8sValidation) validateRendered(ctx context.Context, rendered []byte, dialect string, origin func(kind, name string) string) error {
197		if len(bytes.TrimSpace(rendered)) == 0 {
198			return nil
199		}
200		cmd := kubeconformStdinArgs(rendered, v.kubeconform, v.opts)
201		log.Printf("Running: %s", cmd)
202		out, err := runner.Run(ctx, cmd, nil)
203		if err := kubeconformFailure(out, err); err != nil {
204			return err
205		}
206		noFile := func(string) ([]byte, error) { return nil, errors.New("rendered, not a file") }
207		findings, skipped, err := parseKubeconformOutput(out, v.opts.KubernetesVersion, noFile, origin)
208		if err != nil {
209			return err
210		}
211		v.report.SkippedCustom += skipped
212		for i := range findings {
213			findings[i].IaCType = dialect
214		}
215		v.report.Findings = append(v.report.Findings, findings...)
216		return nil
217	}
218	
219	// helmLint runs helm lint and returns its warnings and errors. helm exits 1
220	// when a chart fails; its messages are still the answer. A run that printed
221	// nothing parseable is logged and yields nothing — the render that follows
222	// will say whether the chart is usable.
223	func helmLint(ctx context.Context, target, chart string, tool ToolSpec) []Finding {
224		cmd := helmArgs(target, chart, tool, "lint")
225		log.Printf("Running: %s", cmd)
226		out, err := runner.Run(ctx, cmd, nil)
227		findings, recognised := parseHelmLint(out, chart, target)
228		if err != nil && !recognised {
229			log.Printf("ERROR [scan/helm] lint %s: %v", chart, err)
230		}
231		return findings
232	}
233	
234	// parseHelmLint turns helm lint's text into findings. The second result says
235	// the output was helm lint's at all.
236	//
237	// A message's path is usually relative to the chart ("templates/cm.yaml"),
238	// but not always: the missing-dependency warning names the chart directory
239	// absolutely — "/scan/charts/broken" in a container, measured on helm 4.3.0.
240	// Both are brought back to a path relative to the repository.
241	func parseHelmLint(out []byte, chart, target string) ([]Finding, bool) {
242		file := func(p string) string { return helmLintPath(p, chart, target) }
243		var findings []Finding
244		recognised := false
245		sc := bufio.NewScanner(bytes.NewReader(out))
246		for sc.Scan() {
247			line := strings.TrimSpace(sc.Text())
248			switch {
249			case strings.HasPrefix(line, "==> Linting"):
250				recognised = true
251			case strings.HasPrefix(line, "Error "):
252				// Printed instead of the messages when the chart could not be
253				// loaded at all.
254				recognised = true
255				findings = append(findings, helmLintFinding(chart, SeverityHigh, strings.TrimPrefix(line, "Error ")))
256			default:
257				m := helmLintLine.FindStringSubmatch(line)
258				if m == nil {
259					continue
260				}
261				recognised = true
262				switch m[1] {
263				case "ERROR":
264					findings = append(findings, helmLintFinding(file(m[2]), SeverityHigh, m[3]))
265				case "WARNING":
266					findings = append(findings, helmLintFinding(file(m[2]), SeverityLow, m[3]))
267				}
268			}
269		}
270		return findings, recognised
271	}
272	
273	// helmLintPath resolves a path helm lint printed to one relative to the
274	// repository.
275	func helmLintPath(p, chart, target string) string {
276		p = strings.TrimSuffix(p, "/")
277		switch {
278		case p == containerScanPath:
279			return "."
280		case strings.HasPrefix(p, containerScanPath+"/"):
281			return strings.TrimPrefix(p, containerScanPath+"/")
282		case filepath.IsAbs(p):
283			if rel, err := filepath.Rel(target, p); err == nil && !strings.HasPrefix(rel, "..") {
284				return filepath.ToSlash(rel)
285			}
286			return filepath.ToSlash(p)
287		default:
288			return path.Join(chart, p)
289		}
290	}
