314	// renderFailure is a chart or an overlay that could not be rendered: nothing
315	// in it was validated, and `helm install` or `kubectl apply -k` would fail the
316	// same way.
317	func renderFailure(source, dialect, file, title string, err error) Finding {
318		detail := err.Error()
319		var exitErr *exitError
320		if errors.As(err, &exitErr) && exitErr.Stderr != "" {
321			detail = strings.TrimSpace(exitErr.Stderr)
322		}
323		first, _, _ := strings.Cut(detail, "\n")
324		return Finding{
325			ID:          K8sRenderID,
326			Title:       title + ": " + first,
327			Description: "The directory could not be rendered, so none of its resources were validated.",
328			Message:     detail,
329			Resolution:  "Render it locally and fix what the tool reports; a chart's dependencies must be vendored in charts/ or fetched with helm dependency build.",
330			Severity:    SeverityHigh,
331			Source:      source,
332			File:        file,
333			IaCType:     dialect,
