337	// helmOrigins maps each rendered resource, by kind and name, to the template
338	// it came from, relative to the repository. helm names the template under the
339	// chart's own name, which need not be its directory's.
340	func helmOrigins(rendered []byte, chart string) map[string]string {
341		origins := map[string]string{}
342		for _, doc := range splitYAMLDocuments(rendered) {
343			var source string
344			for _, line := range strings.Split(doc, "\n") {
345				if m := helmSourceLine.FindStringSubmatch(line); m != nil {
346					source = m[1]
347					break
348				}
349			}
350			if source == "" {
351				continue
352			}
353			var meta struct {
354				Kind     string `yaml:"kind"`
355				Metadata struct {
356					Name string `yaml:"name"`
357				} `yaml:"metadata"`
358			}
359			if yaml.Unmarshal([]byte(doc), &meta) != nil || meta.Kind == "" {
360				continue
361			}
362			key := meta.Kind + "/" + meta.Metadata.Name
363			if _, seen := origins[key]; seen {
364				continue
365			}
366			_, rest, _ := strings.Cut(source, "/")
367			origins[key] = path.Join(chart, rest)
368		}
369		return origins
370	}
