145			case same && !bestSameMajor:
146			case same == bestSameMajor:
147				if c, _ := CompareVersions(opt, best); c >= 0 {
148					continue
149				}
150			default:
151				continue
152			}
153			best, bestSameMajor = opt, same
154		}
155		return best
156	}
