152	// toggleCandidate chooses the candidate under the cursor for its stage, or
153	// releases it. Choosing another one of the same stage replaces the first.
154	func (m Model) toggleCandidate() (tea.Model, tea.Cmd) {
155		if a := m.canSelectCandidate(); !a.Enabled() {
156			return m, m.footer.Warn(a.Reason)
157		}
158		row, _ := m.remediation.table.Selected()
159		if m.remediation.selected[row.Entry] == row.Ref {
160			delete(m.remediation.selected, row.Entry)
161			m.refreshRemediation()
162			return m, nil
163		}
164		if other, clash := m.sharesADefault(row.Entry, row.Ref); clash {
165			return m, m.footer.Warn(fmt.Sprintf(
166				"Stage %s reads the same ARG and has %s chosen — one base image for both",
167				m.remediation.entries[other].StageLabel, m.remediation.selected[other]))
168		}
169		m.remediation.selected[row.Entry] = row.Ref
170		m.refreshRemediation()
171		return m, nil
172	}
