174	// sharesADefault finds another stage of the same file that reads the ARG
175	// default this one does and has a different base chosen. One ARG is one place in
176	// the file: two answers for it cannot both be written.
177	func (m Model) sharesADefault(entry int, ref string) (int, bool) {
178		this := m.remediation.entries[entry]
179		for i, other := range m.remediation.entries {
180			if i == entry || other.File != this.File || other.Stage.Span != this.Stage.Span {
181				continue
182			}
183			if chosen, ok := m.remediation.selected[i]; ok && chosen != ref {
184				return i, true
185			}
186		}
187		return 0, false
188	}
